const axios = require('axios');
const SUPABASE_URL = $env.SUPABASE_URL;
const SERVICE_KEY = $env.SUPABASE_SERVICE_ROLE_KEY;
const headers = { apikey: SERVICE_KEY, Authorization: `Bearer ${SERVICE_KEY}`, 'Content-Type': 'application/json' };

const hoyAR = new Date().toLocaleDateString('en-CA', { timeZone: 'America/Argentina/Buenos_Aires' });
const diaDelMes = parseInt(hoyAR.split('-')[2], 10);

let recurrentes;
try {
  const { data } = await axios.get(`${SUPABASE_URL}/rest/v1/recurrentes`, {
    headers,
    params: { activo: 'eq.true', dia_del_mes: `eq.${diaDelMes}`, select: '*' }
  });
  recurrentes = data;
} catch (error) {
  throw new Error(`No pude leer recurrentes: ${error.message}`);
}

const pendientes = recurrentes.filter((r) => r.ultima_ejecucion !== hoyAR);

let tcUsado = null;
try {
  const { data: tcRows } = await axios.get(`${SUPABASE_URL}/rest/v1/tipo_cambio`, {
    headers, params: { select: 'oficial_venta', order: 'fecha.desc', limit: 1 }
  });
  if (tcRows.length > 0) tcUsado = tcRows[0].oficial_venta;
} catch (error) {
  tcUsado = null;
}

const insertados = [];
for (const r of pendientes) {
  const montoUsd = tcUsado ? Number((r.monto / tcUsado).toFixed(2)) : null;
  const payload = {
    tipo: 'gasto',
    fecha: hoyAR,
    monto_ars: r.monto,
    monto_usd: montoUsd,
    tc_usado: tcUsado,
    moneda_origen: 'ARS',
    categoria_id: r.categoria_id,
    comercio: null,
    descripcion: r.descripcion,
    metodo_pago: r.metodo_pago,
    cuotas_total: 1,
    cuota_nro: 1,
    fuente: 'recurrente',
    transcripcion_raw: null,
    confianza: 'alta'
  };

  try {
    await axios.post(`${SUPABASE_URL}/rest/v1/movimientos`, payload, {
      headers: { ...headers, Prefer: 'return=minimal' }
    });
    await axios.patch(`${SUPABASE_URL}/rest/v1/recurrentes`, { ultima_ejecucion: hoyAR }, {
      headers, params: { id: `eq.${r.id}` }
    });
    insertados.push(`${r.descripcion} — $${r.monto}`);
  } catch (error) {
    throw new Error(`No pude cargar el recurrente "${r.descripcion}": ${error.message}`);
  }
}

return [{ json: { cantidad: insertados.length, lista: insertados.join('\n') } }];
